(function(){if(!window.POL_GREK){console.warn("[pol-grek] data core missing before articles");return}window.POL_GREK.articles=[{slug:"motivaciya-pobochnyy-produkt",title:"\u041C\u043E\u0442\u0438\u0432\u0430\u0446\u0438\u044F \u2014 \u043D\u0435 \u043F\u0440\u0438\u0447\u0438\u043D\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u042D\u0442\u043E \u043F\u043E\u0431\u043E\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0434\u0443\u043A\u0442",category:"\u041C\u043E\u0437\u0433 \u0438 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435",hook:"\u0416\u0434\u0451\u0442\u0435 \xAB\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u044F\xBB \u2014 \u0447\u0430\u0441\u0442\u043E \u0436\u0434\u0451\u0442\u0435 \u0441\u0438\u0433\u043D\u0430\u043B, \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043C\u043E\u0437\u0433 \u043D\u0435 \u0432\u044B\u0434\u0430\u0451\u0442. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435. \u041F\u043E\u0442\u043E\u043C \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435.",readMin:6,relatedBook:"mentalnyy-debag",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u0417\u043D\u0430\u043A\u043E\u043C\u043E: \xAB\u041D\u0430\u0447\u043D\u0443, \u043A\u043E\u0433\u0434\u0430 \u0441\u043E\u0431\u0435\u0440\u0443\u0441\u044C\xBB. \u041D\u0435\u0434\u0435\u043B\u044F. \u041C\u0435\u0441\u044F\u0446. \u041D\u043E\u043B\u044C. \u0418 \u0432 \u0433\u043E\u043B\u043E\u0432\u0435 \u2014 \xAB\u044F \u043F\u0440\u043E\u0441\u0442\u043E \u043B\u0435\u043D\u0438\u0432\u044B\u0439\xBB. \u0427\u0430\u0441\u0442\u043E \u044D\u0442\u043E \u043D\u0435 \u043B\u0435\u043D\u044C. \u042D\u0442\u043E \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u0430\u044F \u0441\u0445\u0435\u043C\u0430: \u0436\u0434\u0430\u0442\u044C \u043C\u043E\u0442\u0438\u0432\u0430\u0446\u0438\u044E, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u0447\u0430\u0442\u044C."},{type:"p",text:"\u041C\u043E\u0442\u0438\u0432\u0430\u0446\u0438\u044F \u2014 \u043D\u0435 \u0441\u0442\u0430\u0440\u0442\u0435\u0440. \u042D\u0442\u043E \u043F\u043E\u0431\u043E\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0434\u0443\u043A\u0442 \u0443\u0436\u0435 \u0438\u0434\u0443\u0449\u0435\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u041C\u043E\u0437\u0433 \u043E\u0445\u043E\u0442\u043D\u0435\u0435 \u043F\u043E\u0434\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0434 \xAB\u044F \u0443\u0436\u0435 \u043D\u0430\u0447\u0430\u043B\xBB, \u0447\u0435\u043C \u043F\u043E\u0434 \u0444\u0430\u043D\u0442\u0430\u0437\u0438\u044E \xAB\u043A\u043E\u0433\u0434\u0430-\u043D\u0438\u0431\u0443\u0434\u044C \u0441\u0442\u0430\u043D\u0435\u0442 \u043B\u0435\u0433\u043A\u043E\xBB."},{type:"h2",text:"\u041F\u043E\u0447\u0435\u043C\u0443 \xAB\u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\xBB \u043F\u043E\u0447\u0442\u0438 \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442"},{type:"p",text:"\u0421\u0438\u0441\u0442\u0435\u043C\u0430 \u044D\u043A\u043E\u043D\u043E\u043C\u0438\u0442 \u0440\u0435\u0441\u0443\u0440\u0441. \u0411\u0435\u0437 \u0441\u0438\u0433\u043D\u0430\u043B\u0430 \xAB\u043F\u0440\u043E\u0446\u0435\u0441\u0441 \u043F\u043E\u0448\u0451\u043B\xBB \u043E\u043D\u0430 \u043D\u0435 \u043B\u044E\u0431\u0438\u0442 \u0442\u0440\u0430\u0442\u0438\u0442\u044C \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435. \u0416\u0434\u0430\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u044F \u2014 \u043A\u0430\u043A \u0441\u0442\u043E\u044F\u0442\u044C \u0443 \u043C\u0430\u0448\u0438\u043D\u044B \u0438 \u0436\u0434\u0430\u0442\u044C, \u043F\u043E\u043A\u0430 \u043E\u043D\u0430 \u043F\u0440\u043E\u0433\u0440\u0435\u0435\u0442\u0441\u044F \u0441\u0430\u043C\u0430. \u0417\u0430 \u0440\u0443\u043B\u0451\u043C \u2014 \u0434\u0440\u0443\u0433\u043E\u0435 \u0434\u0435\u043B\u043E."},{type:"p",text:"\u0412 \u043B\u0435\u043D\u0442\u0435 \u043F\u0440\u043E\u0434\u0430\u044E\u0442 \xAB\u0437\u0430\u0440\u044F\u0434\xBB \u0438 \xAB\u043A\u0430\u043A \u0441\u0435\u0431\u044F \u0437\u0430\u0441\u0442\u0430\u0432\u0438\u0442\u044C\xBB. \u041D\u0430 \u0434\u0435\u043B\u0435: \u0434\u043E\u0444\u0430\u043C\u0438\u043D \u0446\u0435\u043F\u043B\u044F\u0435\u0442\u0441\u044F \u0437\u0430 \u043D\u0430\u0447\u0430\u0442\u043E\u0435 \u0441\u0438\u043B\u044C\u043D\u0435\u0435, \u0447\u0435\u043C \u0437\u0430 \u0438\u0434\u0435\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u043B\u0430\u043D. \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0431\u0435\u0437 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F \u0447\u0430\u0441\u0442\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435. \u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0431\u0435\u0437 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0441\u0433\u043E\u0440\u0430\u0435\u0442 \u0432 \u0441\u043A\u0440\u043E\u043B\u043B\u0435."},{type:"h2",text:"\u0427\u0442\u043E \u0434\u0435\u043B\u0430\u0442\u044C \u0432 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0432\u0442\u043E\u0440\u043D\u0438\u043A"},{type:"p",text:"\u041D\u0435 \xAB\u043F\u0435\u0440\u0435\u0441\u043E\u0431\u0440\u0430\u0442\u044C \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C\xBB. \u0421\u0443\u0437\u0438\u0442\u044C \u0432\u0445\u043E\u0434: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442. \u041D\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u043E\u0434\u043D\u043E \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435. \u0412\u0441\u0442\u0430\u0442\u044C \u0441 \u0434\u0438\u0432\u0430\u043D\u0430. \u0414\u0435\u0441\u044F\u0442\u044C \u043C\u0438\u043D\u0443\u0442 \u2014 \u043D\u0435 \xAB\u0432\u0435\u0441\u044C \u043F\u0440\u043E\u0435\u043A\u0442\xBB. \u041C\u043E\u0437\u0433\u0443 \u043D\u0443\u0436\u0435\u043D \u0444\u0430\u043A\u0442 \xAB\u044F \u0441\u0434\u0435\u043B\u0430\u043B\xBB, \u0430 \u043D\u0435 \u043C\u0430\u043D\u0438\u0444\u0435\u0441\u0442."},{type:"experiment",title:"\u041C\u0438\u043D\u0438-\u044D\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442 \xB7 10 \u043C\u0438\u043D\u0443\u0442",text:"\u0412\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u0437\u0430\u0434\u0430\u0447\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0435. \u0422\u0430\u0439\u043C\u0435\u0440 \u043D\u0430 10 \u043C\u0438\u043D\u0443\u0442. \u0426\u0435\u043B\u044C \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430\u0447\u0430\u0442\u044C, \u043D\u0435 \xAB\u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0438\u0434\u0435\u0430\u043B\u044C\u043D\u043E\xBB. \u041F\u043E\u0441\u043B\u0435 \u0441\u0438\u0433\u043D\u0430\u043B\u0430 \u0440\u0435\u0448\u0438\u0442\u0435: \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0438\u043B\u0438 \u0441\u0442\u043E\u043F. \u0427\u0430\u0449\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442. \u042D\u0442\u043E \u0434\u0430\u043D\u043D\u044B\u0435, \u043D\u0435 \xAB\u0441\u0438\u043B\u0430 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0430\xBB."},{type:"p",text:"\u0415\u0441\u043B\u0438 \u0442\u0435\u043C\u0430 \u043E\u0442\u043A\u043B\u0438\u043A\u0430\u0435\u0442\u0441\u044F \u2014 \u0432 \xAB\u041C\u0435\u043D\u0442\u0430\u043B\u044C\u043D\u043E\u043C \u0434\u0435\u0431\u0430\u0433\u0435\xBB \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u044B, \u043A\u043E\u0433\u0434\u0430 \u043D\u0435\u0442 \u0441\u0438\u043B \u043D\u0430 \xAB\u043B\u0438\u0447\u043D\u043E\u0441\u0442\u043D\u044B\u0439 \u0440\u043E\u0441\u0442\xBB. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u043E\u0442. \u0412 \u043A\u043D\u0438\u0433\u0435 \u2014 \u043A\u0430\u043A \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0442\u044C \u044D\u0442\u043E, \u043A\u043E\u0433\u0434\u0430 \u0441\u043D\u043E\u0432\u0430 \u0445\u043E\u0447\u0435\u0442\u0441\u044F \u0436\u0434\u0430\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F."}]},{slug:"otdyh-ne-lenta",title:"\u041B\u0438\u0441\u0442\u0430\u043D\u0438\u0435 \u043B\u0435\u043D\u0442\u044B \u2014 \u044D\u0442\u043E \u043D\u0435 \u043E\u0442\u0434\u044B\u0445",category:"\u0421\u043E\u043D \u0438 \u044D\u043D\u0435\u0440\u0433\u0438\u044F",hook:"\u041B\u0435\u0436\u0438\u0442\u0435 \u0441 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u043E\u043C \u0438 \u0434\u0443\u043C\u0430\u0435\u0442\u0435, \u0447\u0442\u043E \u043E\u0442\u0434\u044B\u0445\u0430\u0435\u0442\u0435. \u041C\u043E\u0437\u0433 \u0432\u0441\u0451 \u0435\u0449\u0451 \u0436\u0443\u0451\u0442 \u0432\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u043F\u043E\u0442\u043E\u043A \u2014 \u043A\u0430\u043A \u0432\u0435\u0441\u044C \u0434\u0435\u043D\u044C.",readMin:5,relatedBook:"svyashchennye-chasy",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0431\u043E\u0442\u044B \xAB\u043F\u0440\u043E\u0441\u0442\u043E \u043F\u043E\u043B\u0438\u0441\u0442\u0430\u0442\u044C\xBB \u043A\u0430\u0436\u0435\u0442\u0441\u044F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435\u043C. \u041D\u0430 \u0434\u0435\u043B\u0435 \u043C\u043E\u0437\u0433 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0442\u044C \u043D\u043E\u0432\u043E\u0435: \u043B\u0430\u0439\u043A\u0438, \u0447\u0443\u0436\u0438\u0435 \u0443\u0441\u043F\u0435\u0445\u0438, \u043D\u043E\u0432\u043E\u0441\u0442\u0438, \u043F\u0435\u0440\u0435\u043F\u0438\u0441\u043A\u0443. \u042D\u0442\u043E \u043D\u0435 \u0440\u0430\u0437\u0440\u044F\u0434\u043A\u0430. \u042D\u0442\u043E \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u0434\u0432\u0438\u0433 \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u0439."},{type:"p",text:"\u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0439 \u043E\u0442\u0434\u044B\u0445 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0442\u0430\u043C, \u0433\u0434\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u043F\u043E\u0442\u043E\u043A. \u0425\u043E\u0442\u044F \u0431\u044B \u043D\u0430 15\u201320 \u043C\u0438\u043D\u0443\u0442. \u041D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \xAB\u0443\u0435\u0445\u0430\u0442\u044C \u0432 \u0433\u043E\u0440\u044B\xBB. \u0418\u043D\u043E\u0433\u0434\u0430 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0442\u0438\u0448\u0438\u043D\u044B \u0431\u0435\u0437 \u0437\u0430\u0434\u0430\u0447\u0438."},{type:"h2",text:"\u041F\u043E\u0447\u0435\u043C\u0443 \xABslow living\xBB \u043D\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442"},{type:"p",text:"\u0411\u0440\u0435\u043D\u0434 \xAB\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u0439 \u0436\u0438\u0437\u043D\u0438\xBB \u043B\u0435\u0433\u043A\u043E \u043C\u0430\u0441\u043A\u0438\u0440\u0443\u0435\u0442 \u0442\u0443 \u0436\u0435 \u043B\u0435\u043D\u0442\u0443, \u0442\u043E\u043B\u044C\u043A\u043E \u0441 \u044D\u0441\u0442\u0435\u0442\u0438\u0447\u043D\u044B\u043C\u0438 \u0441\u0442\u043E\u0440\u0438\u0441. \u0421\u0443\u0442\u044C \u043D\u0435 \u0432 \u043A\u0440\u0430\u0441\u0438\u0432\u043E\u043C \u043F\u043B\u0435\u0434\u0435. \u0421\u0443\u0442\u044C \u2014 \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u0442\u044C \u0436\u0435\u0432\u0430\u0442\u044C \u043D\u043E\u0432\u044B\u0439 \u0432\u0445\u043E\u0434. \u0420\u0430\u043D\u044C\u0448\u0435 \u044D\u0442\u043E \u043D\u0430\u0437\u044B\u0432\u0430\u043B\u043E\u0441\u044C \u0441\u043A\u0443\u043A\u043E\u0439. \u0421\u0435\u0439\u0447\u0430\u0441 \u2014 \xAB\u043A\u043E\u043D\u0442\u0435\u043D\u0442\u043E\u043C \u043F\u0435\u0440\u0435\u0434 \u0441\u043D\u043E\u043C\xBB."},{type:"h2",text:"\u041C\u0438\u043D\u0438\u043C\u0443\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0447\u0430\u0449\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442, \u0447\u0435\u043C \xAB\u043E\u0442\u043F\u0443\u0441\u043A \u043D\u0430 \u043C\u0435\u0441\u044F\u0446\xBB"},{type:"p",text:"\u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u043E\u0442\u043F\u0443\u0441\u043A\u0430 \u0447\u0435\u0440\u0435\u0437 \u0442\u0440\u0438 \u0434\u043D\u044F \u0441\u043D\u043E\u0432\u0430 \xAB\u0445\u043E\u0447\u0435\u0442\u0441\u044F \u0441\u0431\u0435\u0436\u0430\u0442\u044C\xBB \u2014 \u0434\u0435\u043B\u043E \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \xAB\u043C\u0430\u043B\u043E \u043E\u0442\u0434\u044B\u0445\u0430\u043B\xBB. \u0427\u0430\u0441\u0442\u043E \u2014 \u0432 \u0440\u0435\u0436\u0438\u043C\u0435, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0432\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0435\u0441\u044C: \u0434\u0435\u0434\u043B\u0430\u0439\u043D\u044B, \u044D\u043A\u0440\u0430\u043D, \u043D\u043E\u043B\u044C \u0433\u0440\u0430\u043D\u0438\u0446. \u0422\u0440\u0438 \u0434\u043D\u044F \u0442\u0438\u0448\u0438\u043D\u044B \u0438\u043D\u043E\u0433\u0434\u0430 \u0434\u0430\u044E\u0442 \u0431\u043E\u043B\u044C\u0448\u0435, \u0447\u0435\u043C \u043C\u0435\u0441\u044F\u0446 \xAB\u043E\u0442\u0434\u044B\u0445\u0430\xBB \u0441 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u043E\u043C \u0432 \u0440\u0443\u043A\u0435."},{type:"experiment",title:"15 \u043C\u0438\u043D\u0443\u0442 \u0431\u0435\u0437 \u043F\u043E\u0442\u043E\u043A\u0430",text:"\u0421\u0435\u0433\u043E\u0434\u043D\u044F: 15 \u043C\u0438\u043D\u0443\u0442 \u0431\u0435\u0437 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430 \u0438 \u0444\u043E\u043D\u043E\u0432\u043E\u0433\u043E \u0448\u0443\u043C\u0430. \u041A\u043D\u0438\u0433\u0430, \u0434\u0443\u0448, \u043F\u0440\u043E\u0441\u0442\u043E \u0441\u0438\u0434\u0435\u0442\u044C. \u041D\u0435 \xAB\u043C\u0435\u0434\u0438\u0442\u0430\u0446\u0438\u044F \u043F\u043E \u043C\u0435\u0442\u043E\u0434\u0438\u0447\u043A\u0435\xBB. \u0417\u0430\u043C\u0435\u0442\u044C\u0442\u0435, \u043A\u043E\u0433\u0434\u0430 \u0431\u044B\u043B \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0440\u0430\u0437. \u0415\u0441\u043B\u0438 \u0442\u044F\u0436\u0435\u043B\u043E \u2014 \u044D\u0442\u043E \u0438 \u0435\u0441\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435."},{type:"p",text:"\u0412 \xAB\u0421\u0432\u044F\u0449\u0435\u043D\u043D\u044B\u0445 \u0447\u0430\u0441\u0430\u0445\xBB \u2014 \u0441\u043E\u043D, \u0446\u0438\u043A\u043B\u044B, \u0441\u0432\u0435\u0442 \u0431\u0435\u0437 \u043C\u0438\u0441\u0442\u0438\u043A\u0438. \u0417\u0434\u0435\u0441\u044C \u2014 \u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u0444\u0438\u043B\u044C\u0442\u0440: \u043E\u0442\u0434\u044B\u0445 \u2260 \u043B\u0435\u043D\u0442\u0430."}]},{slug:"kontrol-i-neopredelennost",title:"\u041C\u043E\u0437\u0433 \u043E\u0431\u043E\u0436\u0430\u0435\u0442 \u043E\u0449\u0443\u0449\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F \u2014 \u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u043A\u043E\u0433\u0434\u0430 \u0435\u0433\u043E \u043D\u0435\u0442",category:"\u0421\u0442\u0440\u0435\u0441\u0441 \u0438 \u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435",hook:"\u041F\u0430\u043D\u0438\u043A\u0430 \u043F\u0440\u0438 \u043D\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u043E\u0441\u0442\u0438 \u2014 \u043D\u0435 \xAB\u0441\u043B\u0430\u0431\u044B\u0439 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\xBB. \u0421\u0438\u0441\u0442\u0435\u043C\u0435 \u043D\u0435 \u0434\u0430\u043B\u0438 \u043F\u043E\u043D\u044F\u0442\u043D\u043E\u0433\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0448\u0430\u0433\u0430.",readMin:5,relatedBook:"stress-i-mozg",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u041C\u043E\u0437\u0433 \u043E\u0431\u043E\u0436\u0430\u0435\u0442 \u043E\u0449\u0443\u0449\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F. \u0414\u0430\u0436\u0435 \u043A\u043E\u0433\u0434\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F \u043D\u0435\u0442. \u041E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u043A\u043E\u0433\u0434\u0430 \u0435\u0433\u043E \u043D\u0435\u0442. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0442\u0443\u043C\u0430\u043D \xAB\u0447\u0442\u043E \u0431\u0443\u0434\u0435\u0442\xBB \u0442\u0430\u043A \u0434\u043E\u0440\u043E\u0433\u043E \u0441\u0442\u043E\u0438\u0442: \u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0438 \u043A\u0440\u0443\u0442\u044F\u0442\u0441\u044F, \u0444\u043E\u043D \u043D\u0435 \u043E\u0442\u043F\u0443\u0441\u043A\u0430\u0435\u0442, \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u0443\u0437\u043A\u0438\u043C\u0438."},{type:"p",text:"\u042D\u0442\u043E \u043D\u0435 \u043F\u0440\u0438\u0433\u043E\u0432\u043E\u0440 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0443. \u0427\u0430\u0441\u0442\u043E \u2014 \u0437\u0430\u043F\u0440\u043E\u0441 \u043D\u0430 \u043F\u043E\u043D\u044F\u0442\u043D\u0443\u044E \u0437\u0430\u0434\u0430\u0447\u0443. \u0414\u0430\u0439\u0442\u0435 \u043E\u0434\u0438\u043D \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0439 \u0448\u0430\u0433 \u2014 \u0438 \u0444\u043E\u043D\u0443 \u0447\u0430\u0441\u0442\u043E \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u043B\u0435\u0433\u0447\u0435. \u041D\u0435 \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \xAB\u0436\u0438\u0437\u043D\u044C \u044F\u0441\u043D\u0430 \u043D\u0430 \u0433\u043E\u0434\xBB. \u0410 \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u043F\u043E\u043B\u0443\u0447\u0438\u043B\u0430 \u0441\u0438\u0433\u043D\u0430\u043B: \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0435\u0441\u0442\u044C."},{type:"h2",text:"\u042D\u043D\u0435\u0440\u0433\u0438\u044F \u043D\u0430 \xAB\u043A\u0430\u043A \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C\xBB"},{type:"p",text:"\u0421\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0438\u043B \u0443\u0445\u043E\u0434\u0438\u0442 \u043D\u0430 \u0441\u043E\u043F\u0440\u043E\u0442\u0438\u0432\u043B\u0435\u043D\u0438\u0435 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0432\u043C\u0435\u0441\u0442\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0441 \u043D\u0435\u0439? \xAB\u041A\u0430\u043A \u0434\u043E\u043B\u0436\u043D\u043E\xBB vs \xAB\u043A\u0430\u043A \u0435\u0441\u0442\u044C\xBB \u2014 \u044D\u0442\u043E \u043D\u0435 \u0444\u0438\u043B\u043E\u0441\u043E\u0444\u0438\u044F. \u042D\u0442\u043E \u0440\u0430\u0441\u0445\u043E\u0434. \u0414\u043B\u044F \u0440\u0430\u0431\u043E\u0442\u044B \u0438 \u0441\u0435\u043C\u044C\u0438 \u0432 \u0421\u041D\u0413 (\u0434\u0435\u0444\u0438\u0446\u0438\u0442, \u043D\u043E\u0432\u043E\u0441\u0442\u0438, \u043F\u043B\u0430\u043D\u044B \xAB\u043A\u0430\u043A-\u043D\u0438\u0431\u0443\u0434\u044C\xBB) \u043D\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u043E\u0441\u0442\u044C \u2014 \u0444\u043E\u043D. \u0421 \u043D\u0438\u043C \u043C\u043E\u0436\u043D\u043E \u043D\u0435 \xAB\u043F\u043E\u0431\u0435\u0434\u0438\u0442\u044C\xBB, \u0430 \u0434\u043E\u0437\u0438\u0440\u043E\u0432\u0430\u0442\u044C."},{type:"experiment",title:"\u041E\u0434\u0438\u043D \u0448\u0430\u0433 \u043D\u0430 24 \u0447\u0430\u0441\u0430",text:"\u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435, \u0447\u0442\u043E \xAB\u0432\u0438\u0441\u0438\u0442 \u0442\u0443\u0447\u043A\u043E\u0439\xBB. \u0412\u044B\u0447\u0435\u0440\u043A\u043D\u0438\u0442\u0435 \u0432\u0441\u0451, \u043A\u0440\u043E\u043C\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u2014 \u043D\u0430\u0441\u0442\u043E\u043B\u044C\u043A\u043E \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u043E\u0433\u043E, \u0447\u0442\u043E \u0441\u0442\u044B\u0434\u043D\u043E \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C. \u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435. \u041F\u0430\u043D\u0438\u043A\u0430 \u0447\u0430\u0441\u0442\u043E \u0441\u043F\u0430\u0434\u0430\u0435\u0442 \u043D\u0435 \u043E\u0442 \u043F\u043B\u0430\u043D\u0430 \u043D\u0430 \u0433\u043E\u0434, \u0430 \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0433\u0430."},{type:"p",text:"\u0412 \xAB\u0421\u0442\u0440\u0435\u0441\u0441 \u0438 \u043C\u043E\u0437\u0433\xBB \u2014 \u043A\u0430\u043A \u0443\u0441\u0442\u0440\u043E\u0435\u043D\u0430 \u043F\u0435\u0442\u043B\u044F \u0438 \u0447\u0442\u043E \u0440\u0435\u0430\u043B\u044C\u043D\u043E \u0441\u043D\u0438\u0436\u0430\u0435\u0442 \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0443 \u0431\u0435\u0437 \xAB\u043F\u0440\u043E\u0441\u0442\u043E \u0432\u044B\u0434\u043E\u0445\u043D\u0438\xBB. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u0435\u0440\u0432\u044B\u0439 \u0445\u043E\u0434: \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C \u0434\u043E\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E."}]},{slug:"vygoranie-ne-styd",title:"\xAB\u042F \u043F\u0440\u043E\u0441\u0442\u043E \u0432\u044B\u0433\u043E\u0440\u0435\u043B\u0430\xBB \u0438 \u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435 \u2014 \u043E\u0434\u043D\u0430 \u0444\u0438\u0437\u0438\u043E\u043B\u043E\u0433\u0438\u044F",category:"\u0421\u0442\u0440\u0435\u0441\u0441 \u0438 \u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435",hook:"\u041E\u0449\u0443\u0449\u0435\u043D\u0438\u0435 \u0438 \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C \u2014 \u0440\u0430\u0437\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u0434\u043B\u044F \u043E\u0434\u043D\u043E\u0439 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438. \u0422\u0435\u043B\u043E \u0433\u043E\u0432\u043E\u0440\u0438\u0442 \u0441\u0442\u043E\u043F, \u0430 \u043C\u044B \u0435\u0434\u0435\u043C \u0434\u0430\u043B\u044C\u0448\u0435.",readMin:6,relatedBook:"reset",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u0418\u043D\u043E\u0433\u0434\u0430 \u0433\u043E\u0432\u043E\u0440\u044F\u0442: \xAB\u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435\xBB \u2014 \u043C\u043E\u0434\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u0441\u043A\u0430\u0437\u0430\u0442\u044C \xAB\u044F \u0437\u0430\u0435\u0431\u0430\u043B\u0430\u0441\u044C\xBB. \u0421 \u0442\u043E\u0447\u043A\u0438 \u0437\u0440\u0435\u043D\u0438\u044F \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u044D\u0442\u043E \u0447\u0430\u0441\u0442\u043E \u043E\u0434\u043D\u0430 \u0438\u0441\u0442\u043E\u0440\u0438\u044F. \xAB\u0417\u0430\u0435\u0431\u0430\u043B\u0430\u0441\u044C\xBB \u2014 \u043E\u0449\u0443\u0449\u0435\u043D\u0438\u0435. \xAB\u0412\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435\xBB \u2014 \u0440\u0430\u043C\u043A\u0430: \u0438\u0441\u0442\u043E\u0449\u0435\u043D\u0438\u0435, \u0441\u0431\u043E\u0439 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F, \u0444\u043E\u043D, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u044B\u0445\u043E\u0434\u043D\u044B\u043C\u0438."},{type:"p",text:"\u0421\u0443\u0442\u044C \u043E\u0434\u043D\u0430: \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0436\u043C\u0451\u0442 \u0441\u0442\u043E\u043F, \u0430 \u043C\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u043C. \u0421\u0442\u044B\u0434 (\xAB\u044F \u0434\u043E\u043B\u0436\u043D\u0430 \u0442\u044F\u043D\u0443\u0442\u044C\xBB) \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u043B\u043E\u0439. \u042D\u0442\u043E \u043D\u0435 \u043B\u0435\u043D\u044C \u0438 \u043D\u0435 \xAB\u0441\u043B\u0430\u0431\u044B\u0439 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\xBB."},{type:"h2",text:"\u041D\u0435 \xAB\u0441\u043B\u0435\u0442\u0435\u043B\u0430\xBB. \u0423\u0441\u0442\u0430\u043B\u0430 \u043E\u0442 \u0430\u0431\u0441\u0442\u0440\u0430\u043A\u0442\u043D\u043E\u0433\u043E"},{type:"p",text:"\u0425\u043E\u0447\u0435\u0442\u0441\u044F \xAB\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0440\u0443\u043A\u0430\u043C\u0438\xBB, \xAB\u0441 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u043C\u0438\xBB, \xAB\u0447\u0442\u043E-\u0442\u043E \u043E\u0441\u044F\u0437\u0430\u0435\u043C\u043E\u0435\xBB \u0432\u043C\u0435\u0441\u0442\u043E \u0431\u0435\u0441\u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0445 KPI \u2014 \u043D\u0435 \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044F. \u041C\u043E\u0437\u0433\u0443 \u043F\u043B\u043E\u0445\u043E \u0441 \u0437\u0430\u0434\u0430\u0447\u0430\u043C\u0438 \u0431\u0435\u0437 \u0432\u0438\u0434\u0438\u043C\u043E\u0433\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430. \u0421\u0434\u0435\u043B\u0430\u043B \u2014 \u0430 \u0447\u0442\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u043E\u0441\u044C? \u041D\u0435\u043F\u043E\u043D\u044F\u0442\u043D\u043E. \u0414\u043E\u0444\u0430\u043C\u0438\u043D \u043E\u0442 \u0442\u0430\u043A\u043E\u0433\u043E \u0441\u043A\u0443\u0434\u043D\u044B\u0439. \u041E\u0442 \xAB\u0432\u0438\u0434\u043D\u043E, \u0441\u0434\u0435\u043B\u0430\u043B, \u0434\u0435\u043D\u044C \u0437\u0430\u043A\u0440\u044B\u0442\xBB \u2014 \u0434\u0440\u0443\u0433\u043E\u0439 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440."},{type:"h2",text:"\u041E\u0442\u0434\u044B\u0445 vs \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435"},{type:"p",text:"\u0412\u044B\u0445\u043E\u0434\u043D\u044B\u0435 \xAB\u043E\u0442\u043B\u0435\u0436\u0430\u043B\u0441\u044F \u2014 \u0438 \u0441\u043D\u043E\u0432\u0430 \u0432 \u043D\u043E\u043B\u044C\xBB \u2014 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0430. \u0412\u044B \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0438 \u0432\u0440\u0435\u043C\u044F. \u041D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u2014 \u0440\u0435\u0441\u0443\u0440\u0441. \u0415\u0441\u043B\u0438 \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0434\u0435\u043B\u044E \u043F\u043E\u0441\u043B\u0435 \u043E\u0442\u043F\u0443\u0441\u043A\u0430 \u0441\u043D\u043E\u0432\u0430 \u0445\u043E\u0447\u0435\u0442\u0441\u044F \u0441\u0431\u0435\u0436\u0430\u0442\u044C, \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0443\u0436\u0435 \u043D\u0435 \u043F\u0440\u043E \xAB\u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0432\u044B\u0445\u043E\u0434\u043D\u044B\u0445\xBB, \u0430 \u043F\u0440\u043E \u0441\u0438\u0441\u0442\u0435\u043C\u0443, \u0432 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0432\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0435\u0441\u044C."},{type:"experiment",title:"\u041C\u0430\u0440\u043A\u0435\u0440 \u043D\u0430 2 \u043D\u0435\u0434\u0435\u043B\u0438",text:"\u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435 3 \u0437\u0430\u043D\u044F\u0442\u0438\u044F, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0440\u0430\u043D\u044C\u0448\u0435 \u0437\u0430\u0440\u044F\u0436\u0430\u043B\u0438. \u0417\u0430 14 \u0434\u043D\u0435\u0439: \u0431\u044B\u043B\u043E \u0436\u0438\u0432\u043E\u0435 \u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u2014 \u0438\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \xAB\u043D\u0430\u0434\u043E \u0431\u044B\xBB? \u0415\u0441\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \xAB\u043D\u0430\u0434\u043E \u0431\u044B\xBB \u2014 \u044D\u0442\u043E \u0443\u0436\u0435 \u043D\u0435 \u043F\u0440\u043E \u043B\u0435\u043D\u044C. \u0412 \xABRESET\xBB \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \u043E\u0442\u0434\u044B\u0445 \u043D\u0435 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0438\u0441\u0442\u043E\u0449\u0435\u043D\u0438\u0435 \u0438 \u0441 \u0447\u0435\u0433\u043E \u0440\u0435\u0430\u043B\u044C\u043D\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C (\u0431\u0435\u0437 \u043C\u043E\u0442\u0438\u0432\u0430\u0446\u0438\u043E\u043D\u043D\u044B\u0445 \u043B\u043E\u0437\u0443\u043D\u0433\u043E\u0432)."},{type:"p",text:"\u041D\u0430\u0443\u0447\u043F\u043E\u043F \u2014 \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u0430 \u0432\u0440\u0430\u0447\u0443 \u0438\u043B\u0438 \u043F\u0441\u0438\u0445\u043E\u0442\u0435\u0440\u0430\u043F\u0435\u0432\u0442\u0443, \u0435\u0441\u043B\u0438 \u0442\u044F\u0436\u0435\u043B\u043E. \u0417\u0434\u0435\u0441\u044C \u2014 \u044F\u0437\u044B\u043A, \u0447\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u0442\u044C \u0432\u0438\u043D\u0438\u0442\u044C \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440."}]},{slug:"znaniya-ne-dengi",title:"\u0417\u043D\u0430\u043D\u0438\u044F \u2014 \u043F\u043E\u0442\u0435\u043D\u0446\u0438\u0430\u043B, \u0430 \u043D\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442",category:"\u0414\u0435\u043D\u044C\u0433\u0438 \u0438 \u0440\u0435\u0448\u0435\u043D\u0438\u044F",hook:"\u041F\u043E\u0447\u0435\u043C\u0443 \u0443\u043C\u043D\u044B\u0435 \u043B\u044E\u0434\u0438 \u0431\u044B\u0432\u0430\u044E\u0442 \u0431\u0435\u0437 \u0434\u0435\u043D\u0435\u0433? \u0421\u0438\u043B\u0430 \u043D\u0435 \u0432 \u0437\u043D\u0430\u043D\u0438\u044F\u0445. \u0421\u0438\u043B\u0430 \u0432 \u0442\u043E\u043C, \u0447\u0442\u043E \u0442\u044B \u0441 \u043D\u0438\u043C\u0438 \u0434\u0435\u043B\u0430\u0435\u0448\u044C.",readMin:5,relatedBook:"mozg-i-dengi",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u041C\u043E\u0436\u043D\u043E \u0437\u043D\u0430\u0442\u044C \u0432\u0441\u0451 \u043F\u0440\u043E \u043F\u0438\u0442\u0430\u043D\u0438\u0435 \u2014 \u0438 \u0435\u0441\u0442\u044C \u043A\u0430\u043A \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F. \u041C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0439\u0442\u0438 \u043A\u0443\u0440\u0441 \u043F\u0440\u043E\u0434\u0430\u0436 \u2014 \u0438 \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0437\u0432\u043E\u043D\u043A\u0430. \u0417\u043D\u0430\u043D\u0438\u044F \u2014 \u043F\u043E\u0442\u0435\u043D\u0446\u0438\u0430\u043B. \u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435."},{type:"p",text:"\u041C\u043E\u0437\u0433 \u043E\u0442\u043B\u0438\u0447\u043D\u043E \u043F\u043E\u0434\u043C\u0435\u043D\u044F\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0438\u0437\u0443\u0447\u0435\u043D\u0438\u0435\u043C. \u0415\u0449\u0451 \u043E\u0434\u0438\u043D PDF, \u0435\u0449\u0451 \u0432\u0435\u0431\u0438\u043D\u0430\u0440 \u2014 \u043E\u0449\u0443\u0449\u0435\u043D\u0438\u0435 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u0430 \u0435\u0441\u0442\u044C, \u043D\u0430 \u0441\u0447\u0451\u0442\u0435 \u2014 \u0442\u0438\u0448\u0438\u043D\u0430. \u042D\u0442\u043E \u043D\u0435 \xAB\u0438\u043D\u0442\u0435\u043B\u043B\u0435\u043A\u0442 \u043C\u0435\u0448\u0430\u0435\u0442\xBB. \u042D\u0442\u043E \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u0435\u0435: \u0438\u0437\u0443\u0447\u0430\u0442\u044C, \u0447\u0435\u043C \u0440\u0438\u0441\u043A\u043E\u0432\u0430\u0442\u044C \u043E\u0442\u043A\u0430\u0437\u043E\u043C."},{type:"h2",text:"\u0414\u043B\u044F freelancers, \xAB\u0435\u0449\u0451 \u043A\u0443\u0440\u0441\xBB \u0438 \xAB\u043F\u043E\u0442\u043E\u043C \u043D\u0430\u0447\u043D\u0443\xBB"},{type:"p",text:"\u0412 \u0440\u0443\u0441\u0441\u043A\u043E\u044F\u0437\u044B\u0447\u043D\u043E\u043C \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u0435 \xAB\u043F\u0440\u043E\u043A\u0430\u0447\u043A\u0430\xBB \u0447\u0430\u0441\u0442\u043E = \u043A\u0443\u043F\u0438\u0442\u044C \u043E\u0431\u0443\u0447\u0435\u043D\u0438\u0435. \u041C\u043E\u0437\u0433 \u0440\u0430\u0434: \u0434\u043E\u0444\u0430\u043C\u0438\u043D \u043F\u0440\u0435\u0434\u0432\u043A\u0443\u0448\u0435\u043D\u0438\u044F. \u0410 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u043A\u0430 (\u0437\u0432\u043E\u043D\u043A\u0438, \u0434\u0435\u0431\u0438\u0442\u043E\u0440\u043A\u0430, \u043E\u0444\u0444\u0435\u0440) \u0441\u0442\u043E\u0438\u0442. \u0420\u0430\u0437\u043D\u0438\u0446\u0430 \u043C\u0435\u0436\u0434\u0443 \xAB\u044F \u0437\u043D\u0430\u044E\xBB \u0438 \xAB\u044F \u0441\u0434\u0435\u043B\u0430\u043B\xBB \u2014 \u043D\u0435 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440. \u042D\u0442\u043E \u0430\u0440\u0445\u0438\u0442\u0435\u043A\u0442\u0443\u0440\u0430 \u0432\u044B\u0431\u043E\u0440\u0430."},{type:"experiment",title:"\u0410\u043D\u0442\u0438-\u043A\u0443\u0440\u0441 \u043D\u0430 \u043D\u0435\u0434\u0435\u043B\u044E",text:"\u041D\u043E\u043B\u044C \u043D\u043E\u0432\u044B\u0445 \u043A\u0443\u0440\u0441\u043E\u0432. \u041E\u0434\u043D\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0438\u0437 \u0442\u043E\u0433\u043E, \u0447\u0442\u043E \u0443\u0436\u0435 \u0437\u043D\u0430\u0435\u0442\u0435. \u041C\u0430\u043B\u0435\u043D\u044C\u043A\u043E\u0435. \u0417\u0430\u043A\u0440\u044B\u0442\u043E\u0435. \u0412\u0438\u0434\u0438\u043C\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0434\u043B\u044F \u043C\u043E\u0437\u0433\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0438\u0434\u0435\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u043B\u0430\u043D\u0430."},{type:"p",text:"\u0412 \xAB\u041C\u043E\u0437\u0433 \u0438 \u0434\u0435\u043D\u044C\u0433\u0438\xBB \u2014 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u044B, \u0441\u0442\u0440\u0430\u0445 \u043F\u043E\u0442\u0435\u0440\u044C, \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u0441\u0438\u043B\u0430 \u0432\u043E\u043B\u0438 \u0432\u0435\u0447\u0435\u0440\u043E\u043C\xBB \u0443\u0436\u0435 \u043D\u0435 \u0440\u0435\u0441\u0443\u0440\u0441. \u0417\u0434\u0435\u0441\u044C \u2014 \u0444\u0438\u043B\u044C\u0442\u0440: \u0437\u043D\u0430\u043D\u0438\u044F \u0431\u0435\u0437 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u2014 \u0441\u0430\u043C\u043E\u043E\u0431\u043C\u0430\u043D \u0441 \u0445\u043E\u0440\u043E\u0448\u0435\u0439 \u043E\u0431\u043B\u043E\u0436\u043A\u043E\u0439."}]},{slug:"anti-hype-2-litra",title:"2 \u043B\u0438\u0442\u0440\u0430 \u0432\u043E\u0434\u044B \u2014 \u043C\u0430\u0440\u043A\u0435\u0442\u0438\u043D\u0433, \u0430 \u043D\u0435 \u0444\u0438\u0437\u0438\u043E\u043B\u043E\u0433\u0438\u044F",category:"\u0411\u0438\u043E\u0445\u0430\u043A\u0438\u043D\u0433 \u0431\u0435\u0437 \u0432\u0440\u0435\u0434\u0430",hook:"\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u043E\u043F\u0440\u043E\u0441: \u044D\u0442\u043E \u0434\u0430\u043D\u043D\u044B\u0435 \u2014 \u0438\u043B\u0438 \u043A\u0440\u0430\u0441\u0438\u0432\u044B\u0439 \u043B\u043E\u0437\u0443\u043D\u0433 \u0438\u0437 \u0440\u0438\u043B\u0441\u0430?",readMin:5,relatedBook:"ostorozhnyy-biohaker",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\xAB\u041F\u0435\u0439 2 \u043B\u0438\u0442\u0440\u0430 \u2014 \u0438 \u0436\u0438\u0437\u043D\u044C \u043D\u0430\u043B\u0430\u0434\u0438\u0442\u0441\u044F\xBB. \u0416\u0451\u0441\u0442\u043A\u0430\u044F \u0446\u0438\u0444\u0440\u0430 \u0431\u0435\u0437 \u0432\u0435\u0441\u0430, \u043A\u043B\u0438\u043C\u0430\u0442\u0430, \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u0438 \u0438 \u043F\u043E\u0447\u0435\u043A \u2014 \u0447\u0430\u0449\u0435 \u043C\u0430\u0440\u043A\u0435\u0442\u0438\u043D\u0433, \u0447\u0435\u043C \u0443\u043D\u0438\u0432\u0435\u0440\u0441\u0430\u043B\u044C\u043D\u0430\u044F \u043D\u043E\u0440\u043C\u0430. \xAB\u0427\u0443\u0432\u0441\u0442\u0432\u0443\u044E \u0441\u0435\u0431\u044F \u0430\u043A\u0432\u0430\u0440\u0438\u0443\u043C\u043E\u043C\xBB \u2014 \u0447\u0435\u0441\u0442\u043D\u0430\u044F \u043E\u0431\u0440\u0430\u0442\u043D\u0430\u044F \u0441\u0432\u044F\u0437\u044C \u043E\u0442 \u0442\u0435\u043B\u0430, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043B\u0435\u043D\u0442\u0430 \u0438\u0433\u043D\u043E\u0440\u0438\u0440\u0443\u0435\u0442."},{type:"p",text:"\u0422\u0430\u043A \u0443\u0441\u0442\u0440\u043E\u0435\u043D\u044B \u0434\u0435\u0441\u044F\u0442\u043A\u0438 \xAB\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445\xBB \u043F\u0440\u0430\u0432\u0438\u043B: \u043F\u0440\u043E\u0441\u0442\u043E, \u043A\u0440\u0430\u0441\u0438\u0432\u043E, \u0431\u0435\u0437 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u0430. \u041E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u044B\u0439 \u043F\u043E\u0434\u0445\u043E\u0434 \u2014 \u043D\u0435 \xAB\u043F\u0435\u0439\u0442\u0435 \u043C\u0435\u043D\u044C\u0448\u0435\xBB. \u0410 \xAB\u043D\u0435 \u043F\u043E\u043A\u0443\u043F\u0430\u0439\u0442\u0435 \u0434\u043E\u0433\u043C\u0443\xBB."},{type:"h2",text:"\u0424\u0438\u043B\u044C\u0442\u0440, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0441\u043F\u0430\u0441\u0430\u0435\u0442 \u043A\u043E\u0448\u0435\u043B\u0451\u043A \u0438 \u043D\u0435\u0440\u0432\u044B"},{type:"p",text:"\u0411\u0430\u0437\u0430 (\u0441\u043E\u043D, \u0441\u0432\u0435\u0442, \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435, \u0435\u0434\u0430, \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0430) \u0431\u044C\u0451\u0442 \u0441\u0442\u0435\u043A \u0440\u0438\u0442\u0443\u0430\u043B\u043E\u0432. \u0421\u0432\u044F\u0437\u044C \xAB\u0440\u043E\u0432\u043D\u043E 2 \u043B \u2192 \u0437\u0434\u043E\u0440\u043E\u0432\u044C\u0435 \u0432\u0441\u0435\u043C\xBB \u0432 \u0431\u044B\u0442\u043E\u0432\u044B\u0445 \u0441\u043E\u0432\u0435\u0442\u0430\u0445 \u043E\u0431\u044B\u0447\u043D\u043E \u0441\u043B\u0430\u0431\u0435\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F. \u0422\u043E \u0436\u0435 \u043F\u0440\u043E \xAB\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0445\u043E\u043B\u043E\u0434\u043D\u044B\u0439 \u0434\u0443\u0448\xBB, \xAB\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0442\u0435\u043A\xBB \u0438 \u043F\u0440\u043E\u0447\u0438\u0435 \u0443\u043D\u0438\u0432\u0435\u0440\u0441\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043B\u044F\u0442\u0432\u044B."},{type:"experiment",title:"\u0422\u0440\u0438 \u0432\u043E\u043F\u0440\u043E\u0441\u0430 \u043A \u043B\u044E\u0431\u043E\u043C\u0443 \u0441\u043E\u0432\u0435\u0442\u0443",text:"(1) \u0415\u0441\u0442\u044C \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C \u0438\u043B\u0438 \u0438\u0441\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u043D\u0438\u0435 \u2014 \u0438\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u0439 \u0442\u043E\u043D? (2) \u0415\u0441\u0442\u044C \u0432\u0430\u0448 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 (\u0441\u043E\u043D, \u0441\u0442\u0440\u0435\u0441\u0441, \u0437\u0434\u043E\u0440\u043E\u0432\u044C\u0435)? (3) \u0427\u0442\u043E \u0431\u0443\u0434\u0435\u0442, \u0435\u0441\u043B\u0438 \u043D\u0435\u0434\u0435\u043B\u044E \u043D\u0435 \u0434\u0435\u043B\u0430\u0442\u044C? \u0415\u0441\u043B\u0438 \u043D\u0430 \u0432\u0441\u0435 \u0442\u0440\u0438 \xAB\u043D\u0435 \u0437\u043D\u0430\u044E\xBB \u2014 \u044D\u0442\u043E \u043A\u043E\u043D\u0442\u0435\u043D\u0442, \u043D\u0435 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B."},{type:"p",text:"\u0412 \xAB\u041E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u043E\u043C \u0431\u0438\u043E\u0445\u0430\u043A\u0435\u0440\u0435\xBB \u2014 \u043C\u0430\u043D\u0438\u0444\u0435\u0441\u0442 \xAB\u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0435 \u043D\u0430\u0432\u0440\u0435\u0434\u0438\xBB \u0438 \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u043E\u0432\xBB \u0447\u0430\u0441\u0442\u043E \u0445\u0443\u0436\u0435. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u0435\u0440\u0432\u0430\u044F \u043F\u0440\u0438\u0432\u0438\u0432\u043A\u0430 \u043E\u0442 \u0445\u0430\u0439\u043F\u0430."}]},{slug:"dofamin-predvkushenie",title:"\u0414\u043E\u0444\u0430\u043C\u0438\u043D \u2014 \u0433\u043E\u0440\u043C\u043E\u043D \u043F\u0440\u0435\u0434\u0432\u043A\u0443\u0448\u0435\u043D\u0438\u044F, \u0430 \u043D\u0435 \u0441\u0447\u0430\u0441\u0442\u044C\u044F",category:"\u0414\u0435\u043D\u044C\u0433\u0438 \u0438 \u0440\u0435\u0448\u0435\u043D\u0438\u044F",hook:"\u041C\u043E\u0437\u0433 \u043A\u0430\u0439\u0444\u0443\u0435\u0442 \u043D\u0435 \u043E\u0442 \u043F\u043E\u043A\u0443\u043F\u043A\u0438 \u2014 \u043E\u0442 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u044F. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \xAB\u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0437\u0430\u043A\u0430\u0437\xBB \u043D\u0435 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0434\u044B\u0440\u0443.",readMin:6,relatedBook:"mozg-i-dengi",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u0414\u043E\u0444\u0430\u043C\u0438\u043D \u043F\u0443\u0442\u0430\u044E\u0442 \u0441\u043E \xAB\u0441\u0447\u0430\u0441\u0442\u044C\u0435\u043C\xBB. \u0411\u043B\u0438\u0436\u0435 \u043A \u043F\u0440\u0430\u0432\u0434\u0435: \u043F\u0440\u0435\u0434\u0432\u043A\u0443\u0448\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u0438\u0441\u043A. \u041F\u0438\u043A \u2014 \u043A\u043E\u0433\u0434\u0430 \xAB\u0435\u0449\u0451 \u0447\u0443\u0442\u044C-\u0447\u0443\u0442\u044C\xBB. \u0421\u0430\u043C\u0430 \u043F\u043E\u043A\u0443\u043F\u043A\u0430 \u0443\u0436\u0435 \u0434\u0440\u0443\u0433\u043E\u0439 \u0441\u044E\u0436\u0435\u0442. \u0428\u043E\u043F\u0438\u043D\u0433 \xAB\u0434\u043B\u044F \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F\xBB \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043A\u043E\u0440\u043E\u0442\u043A\u043E \u0438 \u043F\u0440\u043E\u0441\u0438\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u0430."},{type:"p",text:"\u041E\u0442\u0441\u044E\u0434\u0430 \xAB\u0441\u0442\u0430\u0442\u0443\u0441 \u0432 \u043A\u0440\u0435\u0434\u0438\u0442\xBB, \u0432\u0435\u0447\u043D\u0430\u044F \u043A\u043E\u0440\u0437\u0438\u043D\u0430 \u0438 \u043B\u0435\u043D\u0442\u0430: \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0433\u043E\u043D\u0438\u0442\u0441\u044F \u0437\u0430 \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u043C \xAB\u0441\u043A\u043E\u0440\u043E \u043D\u0430\u0433\u0440\u0430\u0434\u0430\xBB, \u0430 \u043D\u0435 \u0437\u0430 \u0443\u0441\u0442\u043E\u0439\u0447\u0438\u0432\u044B\u043C \u0440\u0435\u0441\u0443\u0440\u0441\u043E\u043C. \u0417\u043D\u0430\u0442\u044C \u0431\u044E\u0434\u0436\u0435\u0442 \u043F\u043E\u043B\u0435\u0437\u043D\u043E. \u041D\u043E \u0435\u0441\u043B\u0438 \u0441\u0440\u0435\u0434\u0430 \u0437\u0430\u0442\u043E\u0447\u0435\u043D\u0430 \u043F\u043E\u0434 \u043A\u043B\u0438\u043A \u2014 \u0437\u043D\u0430\u043D\u0438\u044F \u0432\u0435\u0447\u0435\u0440\u043E\u043C \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442."},{type:"h2",text:"\u041D\u0435 \xAB\u0437\u0430\u043F\u0440\u0435\u0442\u0438\u0442\u044C \u0445\u043E\u0442\u0435\u0442\u044C\xBB \u2014 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0442\u0440\u0435\u043D\u0438\u0435"},{type:"p",text:"\u0421\u0438\u043B\u0430 \u0432\u043E\u043B\u0438 \u043A \u0432\u0435\u0447\u0435\u0440\u0443 \u0443\u0436\u0435 \u0441\u044A\u0435\u0434\u0435\u043D\u0430. \u0412\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u0440\u0435\u0434\u0430: 24 \u0447\u0430\u0441\u0430 \u0432\u043D\u0435 \u043A\u043E\u0440\u0437\u0438\u043D\u044B, \u0431\u0435\u0437 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442, \u0441\u043A\u0443\u0447\u043D\u044B\u0435 \u043F\u043B\u0430\u0442\u0435\u0436\u0438 \u0432 \u0430\u0432\u0442\u043E\u043F\u043B\u0430\u0442\u0451\u0436. \u041F\u0440\u0435\u0444\u0440\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u0430\u044F \u043A\u043E\u0440\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442, \u043A\u043E\u0433\u0434\u0430 \u0435\u0439 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u2014 \u043D\u0435 \u043A\u043E\u0433\u0434\u0430 \u0435\u0451 \u0441\u0442\u044B\u0434\u044F\u0442."},{type:"experiment",title:"\u041F\u0440\u0430\u0432\u0438\u043B\u043E 24 \u0447\u0430\u0441\u043E\u0432",text:"\u041D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043F\u043E\u043A\u0443\u043F\u043A\u0430 \u0432\u044B\u0448\u0435 \u0432\u0430\u0448\u0435\u0439 \u043F\u043B\u0430\u043D\u043A\u0438 \u2014 \u0441\u0443\u0442\u043A\u0438 \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0430\u0445, \u043D\u0435 \u0432 \u043A\u043E\u0440\u0437\u0438\u043D\u0435. \u041D\u0430\u043F\u0438\u0448\u0438\u0442\u0435: \xAB\u0447\u0442\u043E \u044F \u0445\u043E\u0447\u0443 \u043F\u043E\u0447\u0443\u0432\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C?\xBB \u0427\u0430\u0441\u0442\u043E \u0447\u0435\u0440\u0435\u0437 \u0441\u0443\u0442\u043A\u0438 \u0445\u043E\u0447\u0435\u0442\u0441\u044F \u0443\u0436\u0435 \u0434\u0440\u0443\u0433\u043E\u0433\u043E."},{type:"p",text:"\u0412 \xAB\u041C\u043E\u0437\u0433 \u0438 \u0434\u0435\u043D\u044C\u0433\u0438\xBB \u2014 \u043A\u0430\u043A \u043C\u043E\u0437\u0433 \u043F\u0440\u043E\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0440\u0438\u0441\u043A\u0438, \u043A\u043E\u0433\u0434\u0430 \u0440\u0435\u0441\u0443\u0440\u0441 \u043D\u0430 \u0434\u043D\u0435. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u043A\u043B\u0438\u043A\xBB \u0442\u0430\u043A \u043B\u0438\u043F\u043A\u0438\u0439."}]},{slug:"proval-v-15",title:"\u041F\u0440\u043E\u0432\u0430\u043B \u0432 15:00 \u2014 \u043D\u0435 \u043B\u0435\u043D\u044C \u0438 \u043D\u0435 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440",category:"\u0421\u043E\u043D \u0438 \u044D\u043D\u0435\u0440\u0433\u0438\u044F",hook:"\u041A \u043E\u0431\u0435\u0434\u0443 \u044F\u0441\u043D\u043E, \u043F\u043E\u0441\u043B\u0435 \u2014 \u0442\u0443\u043C\u0430\u043D? \u0427\u0430\u0449\u0435 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0438\u0441\u0442\u0435\u043C, \u0430 \u043D\u0435 \xAB\u0432\u043E\u0437\u044C\u043C\u0438 \u0441\u0435\u0431\u044F \u0432 \u0440\u0443\u043A\u0438\xBB.",readMin:6,relatedBook:"anatomiya-energii",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u042D\u043D\u0435\u0440\u0433\u0438\u044F \u2014 \u043D\u0435 \u043C\u043E\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0435\u0441\u0443\u0440\u0441. \u042D\u0442\u043E \u043A\u0430\u043A \u043C\u0438\u043D\u0438\u043C\u0443\u043C: \u0442\u043E\u043F\u043B\u0438\u0432\u043E \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435, \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u043D\u0430 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435, \u0446\u0438\u0440\u043A\u0430\u0434\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0443\u0440 (\u0441\u0432\u0435\u0442, \u0432\u0440\u0435\u043C\u044F, \u0441\u043E\u043D). \u0427\u0438\u043D\u0438\u0442\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u043E \u2014 \u0438 \u0443\u0434\u0438\u0432\u043B\u044F\u0435\u0442\u0435\u0441\u044C, \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u0432\u0441\u0451 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435\xBB \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442."},{type:"p",text:"\u041F\u0440\u043E\u0432\u0430\u043B \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u0435\u0434\u0430 \u043C\u0435\u0448\u0430\u044E\u0442: \u0442\u044F\u0436\u0451\u043B\u0430\u044F \u0435\u0434\u0430, \u043C\u0430\u043B\u043E \u0441\u0432\u0435\u0442\u0430, \u0434\u043E\u043B\u0433\u0438\u0439 \u0444\u043E\u043A\u0443\u0441 \u0431\u0435\u0437 \u043F\u0430\u0443\u0437, \u0443\u0436\u0435 \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u043D\u044B\u0439 \u0441\u0442\u0440\u0435\u0441\u0441. \u041C\u043E\u0437\u0433 \u043D\u0435 \xAB\u043B\u043E\u043C\u0430\u0435\u0442\u0441\u044F \u043E\u0442 \u043B\u0435\u043D\u0438\xBB. \u041E\u043D \u044D\u043A\u043E\u043D\u043E\u043C\u0438\u0442."},{type:"h2",text:"\u0427\u0435\u0441\u0442\u043D\u044B\u0439 \u0447\u0435\u043A-\u043B\u0438\u0441\u0442 \u0432\u043C\u0435\u0441\u0442\u043E \xAB\u0441\u0435\u043A\u0440\u0435\u0442\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u0430\xBB"},{type:"p",text:"\u0421\u043E\u043D \u0437\u0430 3 \u043D\u043E\u0447\u0438. \u0414\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0437\u0430 2 \u0434\u043D\u044F. \u0421\u0432\u0435\u0442 \u0443\u0442\u0440\u043E\u043C. \u041F\u0430\u0443\u0437\u0430 \u0431\u0435\u0437 \u044D\u043A\u0440\u0430\u043D\u0430 \u043F\u043E\u0441\u043B\u0435 13:00. \u0415\u0441\u043B\u0438 \xAB\u0442\u0430\u043A \u0441\u0435\u0431\u0435\xBB \u2014 \u043D\u0435 \u043D\u0443\u0436\u0435\u043D \u0441\u0442\u0435\u043A \u0438\u0437 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u0448\u0430\u0433\u043E\u0432. \u041D\u0443\u0436\u043D\u0430 \u0431\u0430\u0437\u0430. \u0425\u0430\u0439\u043F \u043F\u0440\u043E\u0434\u0430\u0451\u0442 \u043D\u0430\u0434\u0435\u0436\u0434\u0443. \u0411\u0430\u0437\u0430 \u043F\u0440\u043E\u0434\u0430\u0451\u0442 \u0441\u043A\u0443\u043A\u0443 \u2014 \u0438 \u0447\u0430\u0449\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442."},{type:"experiment",title:"N-of-1 \u043D\u0430 5 \u0434\u043D\u0435\u0439",text:"\u041E\u0434\u0438\u043D \u0440\u044B\u0447\u0430\u0433: 10\u201315 \u043C\u0438\u043D\u0443\u0442 \u0445\u043E\u0434\u044C\u0431\u044B \u043F\u0440\u0438 \u0434\u043D\u0435\u0432\u043D\u043E\u043C \u0441\u0432\u0435\u0442\u0435 \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u0435\u0434\u0430. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u043D\u0435 \u0442\u0440\u043E\u0433\u0430\u0439\u0442\u0435. \u0422\u0443\u043C\u0430\u043D 1\u201310. \u0415\u0441\u043B\u0438 \u0441\u0434\u0432\u0438\u0433 \u0435\u0441\u0442\u044C \u2014 \u044D\u0442\u043E \u0434\u0430\u043D\u043D\u044B\u0435, \u043D\u0435 \xAB\u044F \u043D\u0430\u043A\u043E\u043D\u0435\u0446 \u0432\u0437\u044F\u043B\u0441\u044F\xBB."},{type:"p",text:"\u0412 \xAB\u0410\u043D\u0430\u0442\u043E\u043C\u0438\u0438 \u044D\u043D\u0435\u0440\u0433\u0438\u0438\xBB \u2014 \u0442\u0440\u0438 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u0438 \u0447\u0442\u043E \u043D\u0435 \u0441\u0442\u043E\u0438\u0442 \u043F\u043E\u043A\u0443\u043F\u0430\u0442\u044C. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 15:00 \xAB\u043B\u043E\u043C\u0430\u0435\u0442\xBB \u0431\u0435\u0437 \u043C\u043E\u0440\u0430\u043B\u0438."}]},{slug:"son-ne-tolko-chasy",title:"\u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0446\u0438\u043A\u043B\u044B \u0441\u043D\u0430, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \xAB8 \u0447\u0430\u0441\u043E\u0432\xBB",category:"\u0421\u043E\u043D \u0438 \u044D\u043D\u0435\u0440\u0433\u0438\u044F",hook:"\u0412\u043E\u0441\u0435\u043C\u044C \u0447\u0430\u0441\u043E\u0432 \u0432 \u043A\u0440\u043E\u0432\u0430\u0442\u0438 \u0441 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u043E\u043C \u2014 \u043D\u0435 \u0442\u043E \u0436\u0435, \u0447\u0442\u043E \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435.",readMin:5,relatedBook:"svyashchennye-chasy",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\xAB\u0421\u043F\u043B\u044E 8 \u0447\u0430\u0441\u043E\u0432 \u0438 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0440\u0430\u0437\u0431\u0438\u0442\xBB \u2014 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0430. \u0427\u0430\u0441\u0442\u043E \u0432 \u043A\u0440\u043E\u0432\u0430\u0442\u0438 \u0438\u0434\u0451\u0442 \u0432\u0442\u043E\u0440\u043E\u0439 \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u0434\u0435\u043D\u044C: \u043B\u0435\u043D\u0442\u0430, \u0441\u0435\u0440\u0438\u0430\u043B, \u043F\u0435\u0440\u0435\u043F\u0438\u0441\u043A\u0430. \u0426\u0438\u043A\u043B\u044B \u0440\u0435\u0436\u0443\u0442\u0441\u044F, \u0441\u0432\u0435\u0442 \u0432\u0435\u0447\u0435\u0440\u043E\u043C \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0440\u0435\u0436\u0438\u043C, \u0443\u0442\u0440\u043E\u043C \u0442\u0435\u043B\u0435\u0444\u043E\u043D \u0431\u044C\u0451\u0442 \u043F\u043E \u043A\u043E\u0440\u0435 \u0434\u043E \u043A\u043E\u0444\u0435."},{type:"p",text:"\u041E\u0442\u0434\u044B\u0445 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0442\u0430\u043C, \u0433\u0434\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u043F\u043E\u0442\u043E\u043A \u2014 \u0445\u043E\u0442\u044F \u0431\u044B \u043D\u0430 15\u201320 \u043C\u0438\u043D\u0443\u0442. \u041D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \xAB\u043C\u0435\u0434\u0438\u0442\u0430\u0446\u0438\u044F \u043F\u043E \u043C\u0435\u0442\u043E\u0434\u0438\u0447\u043A\u0435\xBB. \u0422\u0438\u0448\u0438\u043D\u0430 \u0431\u0435\u0437 \u0437\u0430\u0434\u0430\u0447\u0438."},{type:"h2",text:"\u041C\u0438\u043D\u0438\u043C\u0443\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0447\u0430\u0449\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442, \u0447\u0435\u043C \u0445\u0430\u0439\u043F"},{type:"p",text:"\u0421\u0432\u0435\u0442 \u0443\u0442\u0440\u043E\u043C. \u0422\u0443\u0441\u043A\u043B\u0435\u0435 \u0432\u0435\u0447\u0435\u0440\u043E\u043C. \u0422\u0435\u043B\u0435\u0444\u043E\u043D \u043D\u0435 \u0432 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445 15 \u043C\u0438\u043D\u0443\u0442\u0430\u0445. \u041F\u043E\u0434\u044A\u0451\u043C \u0431\u043B\u0438\u0436\u0435 \u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u043C \u0446\u0438\u043A\u043B\u0430\u043C (~90 \u043C\u0438\u043D\u0443\u0442), \u0430 \u043D\u0435 \u043A \u043C\u0430\u0433\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \xAB\u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0435\xBB. \u0421\u0432\u044F\u0437\u044C \xAB\u0440\u043E\u0432\u043D\u043E 8 \u0447\u0430\u0441\u043E\u0432 \u2192 \u0432\u0441\u0435\u0433\u0434\u0430 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\xBB \u0441\u043B\u0430\u0431\u0435\u0435, \u0447\u0435\u043C \u043E\u0431\u0435\u0449\u0430\u044E\u0442 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0438."},{type:"experiment",title:"15 \u043C\u0438\u043D\u0443\u0442 \u0431\u0435\u0437 \u044D\u043A\u0440\u0430\u043D\u0430 \u043F\u0435\u0440\u0435\u0434 \u0441\u043D\u043E\u043C",text:"\u041F\u044F\u0442\u044C \u0432\u0435\u0447\u0435\u0440\u043E\u0432: 15 \u043C\u0438\u043D\u0443\u0442 \u0431\u0435\u0437 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430. \u041A\u043D\u0438\u0433\u0430, \u0434\u0443\u0448, \u043F\u0440\u043E\u0441\u0442\u043E \u043B\u0435\u0436\u0430\u0442\u044C. \u0423\u0442\u0440\u043E\u043C \u044F\u0441\u043D\u043E\u0441\u0442\u044C 1\u201310. \u0423\u0436\u0435 \u044D\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442, \u043D\u0435 \u0441\u043E\u0432\u0435\u0442 \u0438\u0437 \u0440\u0438\u043B\u0441\u0430."},{type:"p",text:"\u0412 \xAB\u0421\u0432\u044F\u0449\u0435\u043D\u043D\u044B\u0445 \u0447\u0430\u0441\u0430\u0445\xBB \u2014 \u0441\u043E\u043D, \u0446\u0438\u043A\u043B\u044B, \u0441\u0432\u0435\u0442 \u0431\u0435\u0437 \u043C\u0438\u0441\u0442\u0438\u043A\u0438. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \xAB8 \u0447\u0430\u0441\u043E\u0432\xBB \u043D\u0435 \u0440\u0430\u0432\u043D\u044B \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044E."}]},{slug:"prosto-uspokojsya",title:"\xAB\u041F\u0440\u043E\u0441\u0442\u043E \u0443\u0441\u043F\u043E\u043A\u043E\u0439\u0441\u044F\xBB \u2014 \u0431\u0435\u0441\u043F\u043E\u043B\u0435\u0437\u043D\u044B\u0439 \u0441\u043E\u0432\u0435\u0442 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435",category:"\u041C\u043E\u0437\u0433 \u0438 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435",hook:"\u0410\u043C\u0438\u0433\u0434\u0430\u043B\u0430 \u0431\u044B\u0441\u0442\u0440\u0435\u0435 \u043C\u044B\u0441\u043B\u0438. \u042D\u0442\u043E \u043D\u0435 \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0430. \u042D\u0442\u043E \u0430\u0440\u0445\u0438\u0442\u0435\u043A\u0442\u0443\u0440\u0430. \u0412\u043E\u043F\u0440\u043E\u0441 \u2014 \u043A\u0430\u043A \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0440\u0443\u043B\u044C, \u043A\u043E\u0433\u0434\u0430 \u0442\u0435\u043B\u043E \u0443\u0436\u0435 \u0432 \u0443\u0433\u0440\u043E\u0437\u0435.",readMin:6,relatedBook:"ei-2",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\xAB\u041F\u0440\u043E\u0441\u0442\u043E \u0443\u0441\u043F\u043E\u043A\u043E\u0439\u0441\u044F\xBB \u2014 \u043F\u043E\u0447\u0442\u0438 \u0431\u0435\u0441\u043F\u043E\u043B\u0435\u0437\u043D\u044B\u0439 \u0441\u043E\u0432\u0435\u0442, \u043A\u043E\u0433\u0434\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0443\u0436\u0435 \u0432 \u0443\u0433\u0440\u043E\u0437\u0435. \u041F\u043E\u043A\u0430 \u0432\u044B \xAB\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0438 \u043F\u043E\u043D\u0438\u043C\u0430\u0435\u0442\u0435\xBB, \u0442\u0435\u043B\u043E \u0443\u0436\u0435 \u0443\u0448\u043B\u043E \u0432\u043F\u0435\u0440\u0451\u0434. \u042D\u0442\u043E \u043D\u0435 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440. \u042D\u0442\u043E \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C: \u044D\u043C\u043E\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0443\u0440 \u0431\u044B\u0441\u0442\u0440\u0435\u0435 \xAB\u0440\u0430\u0437\u0443\u043C\u043D\u043E\u0433\u043E\xBB."},{type:"p",text:"\u0421\u0442\u044B\u0434 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u043B\u043E\u0439: \xAB\u0441\u043E \u043C\u043D\u043E\u0439 \u0447\u0442\u043E-\u0442\u043E \u043D\u0435 \u0442\u0430\u043A\xBB. \u0422\u043E\u0433\u0434\u0430 STOP, \u0434\u044B\u0445\u0430\u043D\u0438\u0435, \u043F\u0430\u0443\u0437\u0430 \u2014 \u043D\u0435 \u044D\u0437\u043E\u0442\u0435\u0440\u0438\u043A\u0430, \u0430 \u0448\u0430\u043D\u0441 \u0434\u0430\u0442\u044C \u043A\u043E\u0440\u0435 \u0434\u043E\u0433\u043D\u0430\u0442\u044C."},{type:"h2",text:"\u0427\u0442\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043B\u0443\u0447\u0448\u0435 \u043B\u043E\u0437\u0443\u043D\u0433\u0430"},{type:"p",text:"\u041D\u0430\u0437\u0432\u0430\u0442\u044C \u0447\u0443\u0432\u0441\u0442\u0432\u043E \u043E\u0434\u043D\u0438\u043C \u0441\u043B\u043E\u0432\u043E\u043C. 90 \u0441\u0435\u043A\u0443\u043D\u0434: \u0432\u044B\u0434\u043E\u0445 \u0434\u043B\u0438\u043D\u043D\u0435\u0435 \u0432\u0434\u043E\u0445\u0430. \u041E\u0434\u0438\u043D \u043C\u0438\u043A\u0440\u043E\u0448\u0430\u0433 \u043D\u0430 2 \u043C\u0438\u043D\u0443\u0442\u044B. \u041D\u0435 \xAB\u043F\u0440\u043E\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0434\u0435\u0442\u0441\u0442\u0432\u043E \u0437\u0430 \u0432\u0435\u0447\u0435\u0440\xBB \u2014 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0440\u0443\u043B\u044C. \u0415\u0441\u043B\u0438 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0442\u044F\u0436\u0451\u043B\u043E\u0435 \u2014 \u043D\u0430\u0443\u0447\u043F\u043E\u043F \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u0430 \u043F\u043E\u043C\u043E\u0449\u0438 \u0441\u043F\u0435\u0446\u0438\u0430\u043B\u0438\u0441\u0442\u0430."},{type:"experiment",title:"STOP \u043D\u0430 90 \u0441\u0435\u043A\u0443\u043D\u0434",text:"\u0412\u0441\u043F\u043B\u0435\u0441\u043A \u2192 Stop: \u043D\u0430\u0437\u0432\u0430\u0442\u044C \u0447\u0443\u0432\u0441\u0442\u0432\u043E. Take a breath: \u0432\u044B\u0434\u043E\u0445 \u0434\u043B\u0438\u043D\u043D\u0435\u0435 \xD75. Observe: \u0433\u0434\u0435 \u0432 \u0442\u0435\u043B\u0435. Proceed: \u043E\u0434\u0438\u043D \u043C\u0438\u043A\u0440\u043E\u0448\u0430\u0433. \u041D\u0435 \u0438\u0434\u0435\u0430\u043B\u044C\u043D\u043E. \u041F\u0440\u043E\u0441\u0442\u043E \u043D\u0430\u0447\u0430\u0442\u044C."},{type:"p",text:"\u0412 \xAB\u042D\u043C\u043E\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E\u043C \u0438\u043D\u0442\u0435\u043B\u043B\u0435\u043A\u0442\u0435 2.0\xBB (\u0441 \u041B\u043E\u0440\u043E\u0439 \u0413\u0440\u044D\u043A) \u2014 \u0441\u0442\u044B\u0434, \u0434\u043E\u0444\u0430\u043C\u0438\u043D \u0441\u043E\u0446\u0441\u0435\u0442\u0435\u0439, \u043D\u0430\u0432\u044B\u043A\u0438 \u0432\u043C\u0435\u0441\u0442\u043E \xAB\u043F\u0440\u043E\u0441\u0442\u043E \u0443\u0441\u043F\u043E\u043A\u043E\u0439\u0441\u044F\xBB. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \u0441\u043E\u0432\u0435\u0442 \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442."}]},{slug:"minimalnaya-effektivnaya-doza",title:"\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u0430\u044F \u044D\u0444\u0444\u0435\u043A\u0442\u0438\u0432\u043D\u0430\u044F \u0434\u043E\u0437\u0430 \u2014 \u043D\u0435 \u043B\u0435\u043D\u044C, \u0430 \u0444\u0438\u043B\u044C\u0442\u0440",category:"\u0411\u0438\u043E\u0445\u0430\u043A\u0438\u043D\u0433 \u0431\u0435\u0437 \u0432\u0440\u0435\u0434\u0430",hook:"\u0415\u0441\u043B\u0438 \xAB\u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u0443\xBB \u043D\u0443\u0436\u0435\u043D \u0448\u043A\u0430\u0444 \u0441 \u0431\u0430\u043D\u043A\u0430\u043C\u0438 \u2014 \u043E\u043D, \u0441\u043A\u043E\u0440\u0435\u0435 \u0432\u0441\u0435\u0433\u043E, \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0434\u043E\u043B\u0433\u043E.",readMin:5,relatedBook:"biohacking-mozga",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u0430\u044F \u044D\u0444\u0444\u0435\u043A\u0442\u0438\u0432\u043D\u0430\u044F \u0434\u043E\u0437\u0430 \u2014 \u043D\u0435 \u043E\u043F\u0440\u0430\u0432\u0434\u0430\u043D\u0438\u0435 \u043B\u0435\u043D\u0438. \u042D\u0442\u043E \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0441\u0442\u0435\u043A\u0430 \xAB\u043D\u0430 \u0432\u0441\u044F\u043A\u0438\u0439 \u0441\u043B\u0443\u0447\u0430\u0439\xBB. \u0411\u043E\u043B\u044C\u0448\u0435 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u043E\u0432 \u0447\u0430\u0441\u0442\u043E = \u0431\u043E\u043B\u044C\u0448\u0435 \u0448\u0443\u043C\u0430, \u043C\u0435\u043D\u044C\u0448\u0435 \u0441\u043D\u0430, \u0432\u044B\u0448\u0435 \u0442\u0440\u0435\u0432\u043E\u0433\u0430 \xAB\u044F \u0447\u0442\u043E-\u0442\u043E \u0443\u043F\u0443\u0441\u043A\u0430\u044E\xBB."},{type:"p",text:"\u041E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u044B\u0439 \u0431\u0438\u043E\u0445\u0430\u043A\u0435\u0440 \u0441\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442: \u0435\u0441\u0442\u044C \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C? \u0435\u0441\u0442\u044C \u043C\u043E\u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442? \u0447\u0442\u043E \u0431\u0443\u0434\u0435\u0442, \u0435\u0441\u043B\u0438 \u043D\u0435\u0434\u0435\u043B\u044E \u043D\u0435 \u0434\u0435\u043B\u0430\u0442\u044C? \u0411\u0430\u0437\u0430 (\u0441\u043E\u043D, \u0441\u0432\u0435\u0442, \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435, \u0435\u0434\u0430, \u0441\u0442\u0440\u0435\u0441\u0441) \u0431\u044C\u0451\u0442 \xAB2 \u043B\u0438\u0442\u0440\u0430 \u0438 12 \u0447\u0443\u0434\u043E-\u0448\u0430\u0433\u043E\u0432\xBB."},{type:"h2",text:"\u041A\u0430\u043A \u043D\u0435 \u0441\u043B\u043E\u043C\u0430\u0442\u044C \u043F\u0441\u0438\u0445\u0438\u043A\u0443 \xAB\u043F\u0440\u043E\u043A\u0430\u0447\u043A\u043E\u0439\xBB"},{type:"p",text:"\u041E\u0434\u0438\u043D \u0440\u044B\u0447\u0430\u0433 \u2192 \u0438\u0437\u043C\u0435\u0440\u0438\u043C\u044B\u0439 \u044D\u0444\u0444\u0435\u043A\u0442 \u2192 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439. \u041D\u0435 \u0434\u0435\u0441\u044F\u0442\u044C \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u043E. \u0411\u044B\u0441\u0442\u0440\u044B\u0435 \u043C\u0435\u0442\u043E\u0434\u044B \u0447\u0430\u0441\u0442\u043E \u0432\u044B\u0433\u043E\u0440\u0430\u044E\u0442: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u044D\u0439\u0444\u043E\u0440\u0438\u044F, \u043F\u043E\u0442\u043E\u043C \u043F\u0443\u0441\u0442\u043E\u0442\u0430. \u0413\u043B\u0430\u0432\u043D\u044B\u0439 \u043D\u0430\u0432\u044B\u043A \u2014 \u0432\u043E\u0432\u0440\u0435\u043C\u044F \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F."},{type:"experiment",title:"\u041E\u0434\u0438\u043D \u0440\u044B\u0447\u0430\u0433 \u043D\u0430 7 \u0434\u043D\u0435\u0439",text:"\u041E\u0434\u043D\u043E: \u0441\u043E\u043D \u0441\u0442\u0430\u0431\u0438\u043B\u044C\u043D\u0435\u0435 \xB130 \u043C\u0438\u043D, \u0438\u043B\u0438 20 \u043C\u0438\u043D\u0443\u0442 \u0445\u043E\u0434\u044C\u0431\u044B, \u0438\u043B\u0438 \u044D\u043A\u0440\u0430\u043D off \u0437\u0430 30 \u043C\u0438\u043D \u0434\u043E \u0441\u043D\u0430. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u043D\u0435 \u0442\u0440\u043E\u0433\u0430\u0439\u0442\u0435. \u0412 \u043A\u043E\u043D\u0446\u0435 \u043D\u0435\u0434\u0435\u043B\u0438: \u0447\u0442\u043E \u0440\u0435\u0430\u043B\u044C\u043D\u043E \u0441\u0434\u0432\u0438\u043D\u0443\u043B\u043E\u0441\u044C? \u0422\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u043E \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0435."},{type:"p",text:"\u0412 \xAB\u0411\u0438\u043E\u0445\u0430\u043A\u0438\u043D\u0433\u0435 \u043C\u043E\u0437\u0433\u0430\xBB \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u0441\u0432\u0435\u0440\u0445\u0447\u0435\u043B\u043E\u0432\u0435\u043A\xBB \u043A\u043E\u043D\u0447\u0430\u0435\u0442\u0441\u044F \u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435\u043C \u0438 \u0433\u0434\u0435 \u0433\u0440\u0430\u043D\u0438\u0446\u0430 \u0443 \u0445\u0430\u0439\u043F\u0430. \u0417\u0434\u0435\u0441\u044C \u2014 \u0444\u0438\u043B\u044C\u0442\u0440 \u0434\u043E\u0437\u044B."}]},{slug:"kognitivnyy-rezerv",title:"\u041A\u043E\u0433\u043D\u0438\u0442\u0438\u0432\u043D\u044B\u0439 \u0440\u0435\u0437\u0435\u0440\u0432 \u2014 \u043D\u0435 \u043B\u043E\u0442\u0435\u0440\u0435\u044F \u0433\u0435\u043D\u043E\u0432",category:"\u041A\u043E\u0433\u043D\u0438\u0442\u0438\u0432\u043D\u043E\u0435 \u0437\u0434\u043E\u0440\u043E\u0432\u044C\u0435",hook:"\u041C\u043E\u0437\u0433 \u043D\u0435 \xAB\u0441\u0430\u043C \u043A\u0430\u043A-\u043D\u0438\u0431\u0443\u0434\u044C\xBB \u0434\u043E\u0442\u044F\u043D\u0435\u0442 \u0434\u043E \u043F\u0435\u043D\u0441\u0438\u0438. \u0420\u0435\u0437\u0435\u0440\u0432 \u2014 \u0441\u0443\u043C\u043C\u0430 \u0440\u0435\u0448\u0435\u043D\u0438\u0439, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043B\u0438\u0431\u043E \u043A\u043E\u043F\u044F\u0442, \u043B\u0438\u0431\u043E \u0441\u0436\u0438\u0433\u0430\u044E\u0442.",readMin:6,relatedBook:"mozg-na-100",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u0423\u0434\u043E\u0431\u043D\u044B\u0439 \u043C\u0438\u0444: \xAB\u043C\u043D\u0435 \u0443\u0436\u0435 \u043F\u043E\u0437\u0434\u043D\u043E, \u043C\u043E\u0437\u0433 \u043D\u0435 \u0442\u043E\u0442\xBB. \u041F\u0430\u0441\u043F\u043E\u0440\u0442 \u043D\u0435 \u0441\u0442\u0430\u0432\u0438\u0442 \u0431\u043B\u043E\u043A \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438. \u041A\u043E\u0433\u043D\u0438\u0442\u0438\u0432\u043D\u044B\u0435 \u0444\u0443\u043D\u043A\u0446\u0438\u0438 \u043C\u043E\u0433\u0443\u0442 \u0443\u043B\u0443\u0447\u0448\u0430\u0442\u044C\u0441\u044F \u0432 \u0440\u0430\u0437\u043D\u044B\u0445 \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u0445 \u2014 \u043A\u043B\u044E\u0447\u0435\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \xAB\u043C\u043E\u0433\u0443\u0442\xBB. \u041D\u0435 \u0441\u0430\u043C\u043E. \u041D\u0435 \u0443 \u0432\u0441\u0435\u0445. \u041D\u043E \xAB\u043F\u043E\u0437\u0434\u043D\u043E \u043F\u043E \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0443\xBB \u0447\u0430\u0441\u0442\u043E \u2014 \u0441\u0430\u043C\u043E\u0441\u0431\u044B\u0432\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0438."},{type:"p",text:"\u041C\u043E\u0437\u0433 \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u0435\u0442 \u043D\u0435 \u043D\u0430 \u0433\u043E\u0434 \u0440\u043E\u0436\u0434\u0435\u043D\u0438\u044F, \u0430 \u043D\u0430 \u0442\u043E, \u0447\u0435\u043C \u0435\u0433\u043E \u043A\u043E\u0440\u043C\u044F\u0442: \u0441\u043E\u043D, \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435, \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u044C, \u0436\u0438\u0432\u043E\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442. \u041C\u0435\u043D\u044C\u0448\u0435 \u043D\u043E\u0432\u043E\u0433\u043E \u0438 \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u0440\u0430\u043A\u0442\u0438\u043A\u0438 \u2014 \u0438 \u0441\u043D\u0438\u0436\u0435\u043D\u0438\u0435 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442 \u043D\u0435 \xAB\u0438\u0437-\u0437\u0430 \u043B\u0435\u0442\xBB, \u0430 \u0438\u0437-\u0437\u0430 \u043D\u0435\u0434\u043E\u0433\u0440\u0443\u0437\u043A\u0438."},{type:"h2",text:"\u0427\u0442\u043E \u043A\u043E\u043F\u0438\u0442 \u0440\u0435\u0437\u0435\u0440\u0432 (\u0441\u043A\u0443\u0447\u043D\u043E, \u043D\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442)"},{type:"p",text:"\u0421\u043E\u043D. \u0414\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0441 \u043F\u0443\u043B\u044C\u0441\u043E\u043C. \u0417\u0430\u0434\u0430\u0447\u0430 \u0431\u0435\u0437 \u0430\u0432\u0442\u043E\u043F\u0438\u043B\u043E\u0442\u0430: \u044F\u0437\u044B\u043A, \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442, \u0441\u043B\u043E\u0436\u043D\u044B\u0439 \u0442\u0435\u043A\u0441\u0442. \u0427\u0443\u0434\u043E-\u0442\u0430\u0431\u043B\u0435\u0442\u043A\u0438 \u043F\u0440\u043E\u0434\u0430\u044E\u0442 \u043D\u0430\u0434\u0435\u0436\u0434\u0443. \u041F\u0440\u043E\u0442\u043E\u043A\u043E\u043B \u043F\u0440\u043E\u0434\u0430\u0451\u0442 \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u043E\u0441\u0442\u044C. \u0423\u0440\u043E\u0432\u043D\u0438 A\u2013D \u2014 \u0433\u0434\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u043A\u0440\u0435\u043F\u0447\u0435, \u0433\u0434\u0435 \u043E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u043E\u0441\u0442\u044C: A \u2014 \u0441\u0438\u043B\u044C\u043D\u044B\u0435 \u043E\u0431\u0437\u043E\u0440\u044B, D \u2014 \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u044F."},{type:"experiment",title:"\u0421\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u044C 20 \u043C\u0438\u043D\u0443\u0442",text:"\u0422\u0440\u0438 \u0440\u0430\u0437\u0430 \u0432 \u043D\u0435\u0434\u0435\u043B\u044E: 20 \u043C\u0438\u043D\u0443\u0442 \u0447\u0443\u0442\u044C \u0442\u0440\u0443\u0434\u043D\u0435\u0435 \u043A\u043E\u043C\u0444\u043E\u0440\u0442\u0430 (\u043D\u0435 \u0434\u0435\u0434\u043B\u0430\u0439\u043D \u043D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435). \u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442, \u044F\u0437\u044B\u043A, \u0437\u0430\u0434\u0430\u0447\u0430 \u0431\u0435\u0437 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043E\u043A. \u041C\u043E\u0437\u0433\u0443 \u043D\u0443\u0436\u043D\u0430 \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0441 \u0443\u0441\u0438\u043B\u0438\u0435\u043C \u2014 \u043A\u0430\u043A \u043C\u044B\u0448\u0446\u0430\u043C."},{type:"p",text:"\u0412 \xAB\u041C\u043E\u0437\u0433 \u043D\u0430 100+\xBB \u2014 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u044B\u0439 \u043F\u043B\u0430\u043D \u0431\u0435\u0437 \xAB\u0433\u0435\u043D\u0438\u0439 \u0437\u0430 \u043D\u0435\u0434\u0435\u043B\u044E\xBB. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \xAB\u043F\u043E\u0437\u0434\u043D\u043E\xBB \u2014 \u043D\u0435 \u0434\u0438\u0430\u0433\u043D\u043E\u0437, \u0430 \u0447\u0430\u0441\u0442\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430."}]},{slug:"styd-ne-toplivo",title:"\u0421\u0442\u044B\u0434 \u2014 \u043F\u043B\u043E\u0445\u043E\u0439 \u043C\u043E\u0442\u0438\u0432\u0430\u0442\u043E\u0440. \u041E\u043D \u0436\u0440\u0451\u0442 \u0440\u0435\u0441\u0443\u0440\u0441",category:"\u041C\u043E\u0437\u0433 \u0438 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435",hook:"\xAB\u0422\u044B \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0445\u043E\u0447\u0435\u0448\u044C\xBB \u0437\u0432\u0443\u0447\u0438\u0442 \u0436\u0451\u0441\u0442\u043A\u043E \u0438 \u043F\u043E\u0447\u0442\u0438 \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u0447\u0438\u043D\u0438\u0442 \u0441\u0438\u0441\u0442\u0435\u043C\u0443.",readMin:5,relatedBook:"ei-2",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u0421\u0442\u044B\u0434 \u043F\u0440\u043E\u0434\u0430\u044E\u0442 \u043A\u0430\u043A \u0442\u043E\u043F\u043B\u0438\u0432\u043E: \u0443\u0441\u0442\u044B\u0434\u0438\u0441\u044C \u2014 \u0438 \u043F\u043E\u0431\u0435\u0436\u0438\u0448\u044C. \u041D\u0430 \u043F\u0440\u0430\u043A\u0442\u0438\u043A\u0435 \u0441\u0442\u044B\u0434 \u0441\u0443\u0436\u0430\u0435\u0442 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435, \u0443\u0441\u0438\u043B\u0438\u0432\u0430\u0435\u0442 \u0438\u0437\u0431\u0435\u0433\u0430\u043D\u0438\u0435 \u0438 \u0437\u0430\u0435\u0434\u0430\u043D\u0438\u0435 \u043B\u0435\u043D\u0442\u043E\u0439. \u0412 \u0440\u0435\u0436\u0438\u043C\u0435 \u0443\u0433\u0440\u043E\u0437\u044B \u043C\u043E\u0437\u0433 \u043F\u043B\u043E\u0445\u043E \u0443\u0447\u0438\u0442\u0441\u044F \u0438 \u043F\u043B\u043E\u0445\u043E \u043F\u043B\u0430\u043D\u0438\u0440\u0443\u0435\u0442."},{type:"p",text:"\u0421\u0430\u043C\u043E\u0441\u043E\u0441\u0442\u0440\u0430\u0434\u0430\u043D\u0438\u0435 \u2014 \u043D\u0435 \xAB\u0440\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044C \u0432\u0441\u0451\xBB. \u042D\u0442\u043E \u0441\u043D\u0438\u0437\u0438\u0442\u044C \u0448\u0443\u043C, \u0447\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043C\u0435\u0445\u0430\u043D\u0438\u043A\u0435: \u0441\u043E\u043D, \u0433\u0440\u0430\u043D\u0438\u0446\u044B, \u043E\u0434\u0438\u043D \u0448\u0430\u0433. \u042F\u0440\u043B\u044B\u043A \xAB\u043C\u0435\u0440\u0437\u043A\u0438\u0439 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\xBB \u0447\u0430\u0441\u0442\u043E \u043C\u0430\u0441\u043A\u0438\u0440\u0443\u0435\u0442 \u0441\u0440\u0435\u0434\u0443 \u0438 \u043D\u0435\u0434\u043E\u0441\u0431\u043E\u0440\u043A\u0443 \u0441\u0430\u043C\u043E\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F. \u041A\u043D\u0443\u0442 \u043D\u0435 \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442 \u0441\u0431\u043E\u0440\u043A\u0443."},{type:"experiment",title:"\u0424\u0440\u0430\u0437\u0430 \u0432\u043C\u0435\u0441\u0442\u043E \u043A\u043D\u0443\u0442\u0430",text:"\u0412\u043C\u0435\u0441\u0442\u043E \xAB\u044F \u043E\u043F\u044F\u0442\u044C \u043D\u0438\u0447\u0435\u0433\u043E\xBB \u2014 \xAB\u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u0438\u0441\u0442\u0435\u043C\u0435 \u0442\u044F\u0436\u0435\u043B\u043E; \u043A\u0430\u043A\u043E\u0439 \u043E\u0434\u0438\u043D \u0448\u0430\u0433 \u043D\u0430 5 \u043C\u0438\u043D\u0443\u0442 \u0440\u0435\u0430\u043B\u0435\u043D?\xBB. \u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435. \u0421\u0442\u044B\u0434 \u043C\u043E\u0436\u043D\u043E \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u0442\u044C \u043F\u043E\u0437\u0436\u0435. \u0421\u0435\u0439\u0447\u0430\u0441 \u2014 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435."},{type:"p",text:"\u0412 EI 2.0 \u2014 \u0441\u0442\u044B\u0434, \u0432\u0438\u043D\u0430, \u043D\u0430\u0432\u044B\u043A\u0438. \u0417\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0447\u0435\u043C\u0443 \u0441\u0442\u044B\u0434 \u043A\u0430\u043A \xAB\u043C\u043E\u0442\u0438\u0432\u0430\u0446\u0438\u044F\xBB \u0441\u044A\u0435\u0434\u0430\u0435\u0442 \u0440\u0435\u0441\u0443\u0440\u0441."}]},{slug:"neopredelennost-odin-shag",title:"\u041D\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u043E\u0441\u0442\u044C \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u043D\u0435 \u043F\u043B\u0430\u043D\u043E\u043C \u043D\u0430 \u0433\u043E\u0434, \u0430 \u043E\u0434\u043D\u0438\u043C \u0448\u0430\u0433\u043E\u043C",category:"\u0421\u0442\u0440\u0435\u0441\u0441 \u0438 \u0432\u044B\u0433\u043E\u0440\u0430\u043D\u0438\u0435",hook:"\u041C\u043E\u0437\u0433 \u043E\u0431\u043E\u0436\u0430\u0435\u0442 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C. \u041E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u043A\u043E\u0433\u0434\u0430 \u0435\u0433\u043E \u043D\u0435\u0442. \u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u043F\u043B\u0430\u043D \u0438\u043D\u043E\u0433\u0434\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0448\u0443\u043C\u0430. \u041C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0448\u0430\u0433 \u2014 \u0441\u043D\u0438\u0436\u0430\u0435\u0442.",readMin:5,relatedBook:"stress-i-mozg",source:"Threads \xB7 pol.grek",body:[{type:"p",text:"\u041D\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u043E\u0441\u0442\u044C \u0436\u0440\u0451\u0442 \u0440\u0435\u0441\u0443\u0440\u0441: \u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0438 \u043A\u0440\u0443\u0442\u044F\u0442\u0441\u044F, \u0444\u043E\u043D \u043D\u0435 \u043E\u0442\u043F\u0443\u0441\u043A\u0430\u0435\u0442, \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u0442\u0443\u043D\u043D\u0435\u043B\u044C\u043D\u044B\u043C\u0438. \u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u043F\u043B\u0430\u043D \u043D\u0430 \u0433\u043E\u0434 \u0438\u043D\u043E\u0433\u0434\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0448\u0443\u043C\u0430. \u041C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0439 \u0448\u0430\u0433 \u2014 \u0441\u043D\u0438\u0436\u0430\u0435\u0442."},{type:"p",text:"\u0414\u0430\u0439\u0442\u0435 \u0441\u0438\u0441\u0442\u0435\u043C\u0435 \u043E\u0434\u043D\u0443 \u0437\u0430\u0434\u0430\u0447\u0443 \u043D\u0430 24 \u0447\u0430\u0441\u0430 \u2014 \u043D\u0430\u0441\u0442\u043E\u043B\u044C\u043A\u043E \u043C\u0435\u043B\u043A\u0443\u044E, \u0447\u0442\u043E \u0441\u0442\u044B\u0434\u043D\u043E \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C. \u041F\u0430\u043D\u0438\u043A\u0430 \u0447\u0430\u0441\u0442\u043E \u0441\u043F\u0430\u0434\u0430\u0435\u0442 \u043D\u0435 \u043E\u0442 \xAB\u043F\u043E\u043B\u043D\u043E\u0439 \u044F\u0441\u043D\u043E\u0441\u0442\u0438 \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043E\xBB, \u0430 \u043E\u0442 \u0441\u0438\u0433\u043D\u0430\u043B\u0430: \xAB\u044F \u0443\u0436\u0435 \u0434\u0432\u0438\u043D\u0443\u043B\u0441\u044F\xBB. \u042D\u0442\u043E \u043D\u0435 \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C. \u042D\u0442\u043E \u0437\u0430\u043F\u0440\u043E\u0441 \u043D\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043C\u043E\u0436\u043D\u043E \u0434\u0430\u0442\u044C \u0434\u043E\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E."},{type:"experiment",title:"\u041A\u0430\u0440\u0442\u043E\u0447\u043A\u0430 \u043D\u0430 \u0441\u0443\u0442\u043A\u0438",text:"\u041D\u0430 \u0431\u0443\u043C\u0430\u0433\u0435: \xAB\u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0441\u0434\u0435\u043B\u0430\u044E ___\xBB. \u0411\u0435\u0437 \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u043F\u0443\u043D\u043A\u0442\u0430. \u0412\u0435\u0447\u0435\u0440\u043E\u043C \u2014 \u0433\u0430\u043B\u043E\u0447\u043A\u0430 \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u043D\u043E\u0441 \u0441 \u043F\u0440\u0438\u0447\u0438\u043D\u043E\u0439 \u0432 \u043E\u0434\u043D\u043E \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435. \u041D\u0435 \u043E\u0442\u0447\u0451\u0442 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u0438\u043A\u0443. \u0421\u0438\u0433\u043D\u0430\u043B \u043C\u043E\u0437\u0433\u0443."},{type:"p",text:"\u0412 \xAB\u0421\u0442\u0440\u0435\u0441\u0441 \u0438 \u043C\u043E\u0437\u0433\xBB \u2014 \u043F\u0435\u0442\u043B\u044F \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0442 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F \u0431\u0435\u0437 \xAB\u043F\u0440\u043E\u0441\u0442\u043E \u0440\u0430\u0441\u0441\u043B\u0430\u0431\u044C\u0441\u044F\xBB. \u0417\u0434\u0435\u0441\u044C \u2014 \u043E\u0434\u0438\u043D \u0448\u0430\u0433 \u0432\u043C\u0435\u0441\u0442\u043E \u043F\u043B\u0430\u043D\u0430 \u043D\u0430 \u0433\u043E\u0434."}]}]})();
